<template><Button type="button" variant="outline" @click="open=true">Выбрать из медиатеки</Button><Dialog :open="open" @update:open="open=$event"><DialogContent><DialogHeader><DialogTitle>Медиатека</DialogTitle></DialogHeader><input type="file" multiple accept="image/*" @change="upload"><div class="grid grid-cols-4 gap-2"><button v-for="f in files" :key="f.id" type="button" @click="select(f.id)"><img :src="f.url" class="h-20 w-20 object-cover"/></button></div><Button type="button" @click="attach">Добавить</Button></DialogContent></Dialog></template>
<script setup lang="ts">import{ref,watch}from'vue';import axios from'axios';import{Button}from'@/components/ui/button';import{Dialog,DialogContent,DialogHeader,DialogTitle}from'@/components/ui/dialog';const p=defineProps<{productId:number}>();const e=defineEmits(['attached']);const open=ref(false),files=ref<any[]>([]),ids=ref<number[]>([]);watch(open,async v=>{if(v)files.value=(await axios.get('products/media-library',{params:{per_page:100}})).data.data.data??[]});const select=(id:number)=>ids.value=ids.value.includes(id)?ids.value.filter(x=>x!==id):[...ids.value,id];const upload=async(ev:Event)=>{const d=new FormData;Array.from((ev.target as HTMLInputElement).files??[]).forEach(f=>d.append('files[]',f));await axios.post('products/media-library',d);files.value=(await axios.get('products/media-library')).data.data.data??[]};const attach=async()=>{e('attached',(await axios.post(`products/${p.productId}/media-library/attach`,{media_ids:ids.value})).data.data);open.value=false}</script>
